<script setup>
import { computed,ref } from 'vue'

const props=defineProps({apiBase:{type:String,required:true},initialToken:{type:String,default:''}})
const open=ref('list-subscribers'),token=ref(props.initialToken||''),testChannel=ref('whatsapp'),testResult=ref(''),testStatus=ref(''),testing=ref(false)

const endpoints=[
{id:'list-subscribers',method:'GET',path:'/subscribers',title:'List subscribers',scope:'subscribers:read',desc:'List WhatsApp and Telegram subscribers in the API key workspace.',params:[['channel','query','Optional: whatsapp or telegram']],response:'{"data":[{"id":"whatsapp:1","channel":"whatsapp","subscriber_id":"27829640758","name":"Jan Venter","fields":{},"tags":[],"conversation":{"status":"resolved"}}],"count":1}',errors:'401 Invalid/revoked key · 403 Missing subscribers:read',tryable:true},
{id:'create-subscriber',method:'POST',path:'/subscribers',title:'Create WhatsApp subscriber',scope:'subscribers:write',desc:'Create a WhatsApp subscriber. Telegram users must first interact with the bot.',body:'{"channel":"whatsapp","subscriber_id":"27829640758","name":"Jan Venter"}',response:'{"id":"whatsapp:1","channel":"whatsapp","subscriber_id":"27829640758"}',errors:'400 Invalid channel/data · 401 Invalid key · 403 Missing subscribers:write · 409 Subscriber exists'},
{id:'get-subscriber',method:'GET',path:'/subscribers/{id}',title:'Get subscriber',scope:'subscribers:read',desc:'Return one subscriber including profile, fields, tags and conversation state.',params:[['id','path','Stable reference, e.g. whatsapp:1 or telegram:27']],response:'{"id":"whatsapp:1","channel":"whatsapp","subscriber_id":"27829640758","fields":{},"tags":[],"conversation":{}}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber not found'},
{id:'update-subscriber',method:'PATCH',path:'/subscribers/{id}',title:'Update subscriber profile',scope:'subscribers:write',desc:'Update supported subscriber profile properties.',body:'{"name":"Updated Name"}',response:'{"id":"whatsapp:1","name":"Updated Name"}',errors:'400 Invalid data · 401 Invalid key · 403 Missing scope · 404 Not found'},
{id:'delete-subscriber',method:'DELETE',path:'/subscribers/{id}',title:'Archive subscriber',scope:'subscribers:write',desc:'Archive/remove a subscriber while preserving platform history where applicable.',response:'{"ok":true}',errors:'401 Invalid key · 403 Missing scope · 404 Not found'},
{id:'custom-fields',method:'GET',path:'/custom-fields',title:'List custom fields',scope:'fields:read',desc:'List available field definitions and stable keys for the workspace.',response:'{"data":[{"key":"company","name":"Company","type":"text"}],"count":1}',errors:'401 Invalid key · 403 Missing fields:read'},
{id:'subscriber-fields',method:'GET',path:'/subscribers/{id}/fields',title:'Read subscriber fields',scope:'fields:read',desc:'Read system and custom field values by stable field key.',response:'{"subscriber":"whatsapp:1","fields":{"company":"Myself!"}}',errors:'401 Invalid key · 403 Missing scope · 404 Not found'},
{id:'set-fields',method:'PATCH',path:'/subscribers/{id}/fields',title:'Set subscriber fields',scope:'fields:write',desc:'Set one or more custom fields using stable keys rather than internal IDs.',body:'{"fields":{"company":"Route 2 Market Solutions","order_number":"ORD-12345"}}',response:'{"subscriber":"whatsapp:1","fields":{"company":"Route 2 Market Solutions"}}',errors:'400 Unknown/invalid field · 401 Invalid key · 403 Missing fields:write · 404 Subscriber not found'},
{id:'tags',method:'GET',path:'/tags',title:'List tags',scope:'tags:read',desc:'List tags available in the workspace.',response:'{"data":[{"id":1,"name":"VIP"}],"count":1}',errors:'401 Invalid key · 403 Missing tags:read'},
{id:'add-tag',method:'POST',path:'/subscribers/{id}/tags',title:'Assign or create tag',scope:'tags:write',desc:'Assign an existing tag or create/assign a tag by name.',body:'{"name":"VIP"}',response:'{"ok":true,"tag":{"id":1,"name":"VIP"}}',errors:'400 Invalid tag · 401 Invalid key · 403 Missing scope · 404 Subscriber not found'},
{id:'remove-tag',method:'DELETE',path:'/subscribers/{id}/tags/{tag_id}',title:'Remove tag',scope:'tags:write',desc:'Remove a tag assignment from a subscriber.',response:'{"ok":true}',errors:'401 Invalid key · 403 Missing scope · 404 Subscriber/tag not found'},
{id:'conversation',method:'PATCH',path:'/subscribers/{id}/conversation',title:'Update conversation',scope:'conversations:write',desc:'Assign an agent and/or change the Live Chat conversation status.',body:'{"status":"open","assigned_user_id":2}',response:'{"ok":true,"status":"open","assigned_user_id":2}',errors:'400 Invalid status/agent · 401 Invalid key · 403 Missing scope · 404 Conversation not found'},
{id:'flows',method:'GET',path:'/bot-flows',title:'List bot flows',scope:'flows:read',desc:'List channel-targeted bot flows available to the workspace.',params:[['channel','query','Optional: whatsapp or telegram']],response:'{"data":[{"id":1,"name":"Welcome Test","channel":"whatsapp","status":"active"}],"count":1}',errors:'401 Invalid key · 403 Missing flows:read',tryable:true},
{id:'trigger',method:'POST',path:'/bot-flows/{flow_id}/trigger',title:'Trigger bot flow',scope:'flows:trigger',desc:'Start an active WhatsApp or Telegram flow. Custom fields can be populated before execution and restart can replace an existing session.',params:[['flow_id','path','Flow ID returned by GET /bot-flows']],body:'{"subscriber":"27829640758","fields":{"order_number":"ORD-12345","campaign_source":"woocommerce"},"restart":true}',response:'{"ok":true,"flow_id":1,"flow":"Welcome Test","channel":"whatsapp","subscriber":"whatsapp:1","status":"waiting","waiting_for":"button"}',errors:'400 Invalid subscriber/fields · 401 Invalid key · 403 Missing flows:trigger · 404 Flow/subscriber not found · 409 Active session conflict'}
]
const methodClass=e=>e.method.toLowerCase()
function curlFor(e){let url=props.apiBase+e.path.replace('{id}','whatsapp:1').replace('{tag_id}','1').replace('{flow_id}','1');if(e.id==='list-subscribers'||e.id==='flows')url+=`?channel=${testChannel.value}`;let s=`curl -sS -X ${e.method} \\\n  -H "Authorization: Bearer wac_live_YOUR_API_KEY"`;if(e.body)s+=` \\\n  -H "Content-Type: application/json"`;s+=` \\\n  "${url}"`;if(e.body)s+=` \\\n  -d '${e.body}'`;return s}
async function tryGet(e){if(!token.value.trim())return testResult.value='Enter a full wac_live_ API key first.';testing.value=true;testResult.value='';testStatus.value='';try{let url=props.apiBase+e.path;if(e.id==='list-subscribers'||e.id==='flows')url+=`?channel=${encodeURIComponent(testChannel.value)}`;const started=performance.now(),r=await fetch(url,{headers:{Authorization:`Bearer ${token.value.trim()}`}});const text=await r.text();testStatus.value=`HTTP ${r.status} · ${Math.round(performance.now()-started)} ms`;try{testResult.value=JSON.stringify(JSON.parse(text),null,2)}catch{testResult.value=text||'(empty response)'}}catch(err){testStatus.value='Request failed';testResult.value=err.message}finally{testing.value=false}}
</script>

<template><div class="docs-intro"><div><p class="eyebrow">Developer API v1</p><h2>API reference</h2><p>Workspace-scoped REST API. Every request uses a Bearer API key and the permission shown on each endpoint.</p></div><div class="auth"><b>Authorization</b><code>Bearer wac_live_…</code></div></div>
<div class="try-card"><div><div><b>Try API</b><p>Paste a full API key for this browser session. It is not saved by WA Connect.</p></div><input v-model="token" type="password" autocomplete="off" placeholder="wac_live_…"/><select v-model="testChannel"><option value="whatsapp">WhatsApp</option><option value="telegram">Telegram</option></select></div><p class="hint">GET endpoints marked “Try” can be executed here. Successful requests also appear under Request Logs.</p></div>
<div class="api-reference"><article v-for="e in endpoints" :key="e.id" class="api-endpoint" :class="{expanded:open===e.id}"><button class="endpoint-summary" @click="open=open===e.id?'':e.id"><b :class="methodClass(e)">{{e.method}}</b><code>{{e.path}}</code><span>{{e.title}}</span><i>{{e.scope}}</i><em>{{open===e.id?'−':'+'}}</em></button><div v-if="open===e.id" class="endpoint-detail"><p>{{e.desc}}</p><div class="detail-grid"><section><h4>Required scope</h4><code class="scope-code">{{e.scope}}</code><template v-if="e.params"><h4>Parameters</h4><div v-for="p in e.params" :key="p[0]" class="param"><code>{{p[0]}}</code><b>{{p[1]}}</b><span>{{p[2]}}</span></div></template><template v-if="e.body"><h4>Request body</h4><pre>{{JSON.stringify(JSON.parse(e.body),null,2)}}</pre></template><h4>Errors</h4><p class="errors">{{e.errors}}</p></section><section><h4>cURL</h4><pre>{{curlFor(e)}}</pre><h4>Example response</h4><pre>{{JSON.stringify(JSON.parse(e.response),null,2)}}</pre></section></div><div v-if="e.tryable" class="try-row"><button :disabled="testing" @click="tryGet(e)">{{testing?'Running…':'▶ Try '+e.method}}</button><span>Uses {{testChannel}} channel</span></div><div v-if="e.tryable&&testResult" class="try-result"><b>{{testStatus}}</b><pre>{{testResult}}</pre></div></div></article></div></template>

<style scoped>
.docs-intro{display:flex;justify-content:space-between;gap:20px;align-items:center;background:#fff;border:1px solid #dfe7e3;border-radius:14px;padding:20px 22px;margin-bottom:14px}.docs-intro h2{margin:3px 0 5px}.docs-intro p{margin:0;color:#74867e}.eyebrow{text-transform:uppercase;color:#119052!important;font-size:11px;font-weight:800;letter-spacing:.08em}.auth{display:grid;gap:5px;text-align:right;font-size:11px}.auth code{background:#102c21;color:#d9f7e7;padding:8px 10px;border-radius:7px}.try-card{background:#edf8f2;border:1px solid #c9e7d6;border-radius:12px;padding:14px 16px;margin-bottom:14px}.try-card>div{display:grid;grid-template-columns:minmax(260px,1fr) minmax(280px,520px) 130px;gap:12px;align-items:center}.try-card b{font-size:14px}.try-card p{margin:3px 0 0;color:#70837a;font-size:11px}.try-card input,.try-card select{border:1px solid #cbdcd3;background:#fff;border-radius:8px;padding:10px}.try-card .hint{margin-top:9px}.api-reference{display:grid;gap:8px}.api-endpoint{background:#fff;border:1px solid #dfe7e3;border-radius:11px;overflow:hidden}.api-endpoint.expanded{border-color:#afd9c1}.endpoint-summary{width:100%;display:grid;grid-template-columns:62px 300px minmax(180px,1fr) 160px 24px;gap:12px;align-items:center;text-align:left;border:0;background:#fff;padding:12px 14px;cursor:pointer}.endpoint-summary>b{font-size:10px;border-radius:5px;padding:5px 6px;text-align:center;background:#e9f6ef;color:#168452}.endpoint-summary>b.post{background:#e9f1fb;color:#316aa0}.endpoint-summary>b.patch{background:#fff4df;color:#936a18}.endpoint-summary>b.delete{background:#faecec;color:#a33}.endpoint-summary>span{font-weight:700;color:#294238}.endpoint-summary>i{font-style:normal;font-size:10px;color:#628074;background:#f0f5f2;padding:4px 7px;border-radius:999px;width:max-content}.endpoint-summary>em{font-style:normal;font-size:20px;color:#188451}.endpoint-detail{border-top:1px solid #edf1ef;padding:17px 18px;background:#fbfdfc}.endpoint-detail>p{color:#667c72;margin:0 0 15px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.detail-grid section{min-width:0}.detail-grid h4{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#61766c;margin:14px 0 7px}.detail-grid h4:first-child{margin-top:0}.scope-code{display:inline-block;background:#e9f6ef;color:#117947;padding:5px 8px;border-radius:6px}.detail-grid pre,.try-result pre{white-space:pre-wrap;word-break:break-word;background:#102c21;color:#dcf4e8;padding:12px;border-radius:8px;font-size:11px;line-height:1.45;max-height:330px;overflow:auto}.param{display:grid;grid-template-columns:120px 55px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid #edf1ef;font-size:11px}.param b{text-transform:uppercase;color:#799087;font-size:9px}.errors{font-size:11px;color:#8c5959!important}.try-row{display:flex;align-items:center;gap:10px;margin-top:14px;border-top:1px solid #e6eeea;padding-top:14px}.try-row button{border:0;background:#13a65b;color:#fff;border-radius:8px;padding:9px 13px;font-weight:800;cursor:pointer}.try-row button:disabled{opacity:.5}.try-row span{font-size:11px;color:#71847a}.try-result{margin-top:12px}.try-result>b{font-size:11px;color:#167d4d}.try-result pre{margin-bottom:0}@media(max-width:1100px){.endpoint-summary{grid-template-columns:62px 1fr 24px}.endpoint-summary>span{grid-column:2}.endpoint-summary>i{display:none}.detail-grid{grid-template-columns:1fr}.try-card>div{grid-template-columns:1fr}.auth{display:none}}
</style>